use std::{error::Error,path::Path,sync::mpsc::sync_channel,time::Instant};
use uls_parser::archive::ZipExtractor;
use uls_core::records::UlsRecord;
fn consume(record: uls_parser::Result<UlsRecord>) -> Result<(),Box<dyn Error>> {
    let record=record?;
    std::hint::black_box(&record);
    Ok(())
}
fn main()->Result<(),Box<dyn Error>> {
    let args:Vec<_>=std::env::args().skip(1).collect();
    let mode=args.first().ok_or("expected serial, records or counts")?;
    if !["serial","records","counts","recycle"].contains(&mode.as_str()) {return Err("invalid mode".into())}
    let start=Instant::now();
    let mut records=0usize;
    for path in &args[1..] {
        let mut zip=ZipExtractor::open(Path::new(path))?;
        for file in zip.list_dat_files() {
            if mode=="serial" {
                zip.process_dat_streaming(&file,|line|{consume(line.to_record()).unwrap(); records+=1;true})?;
            } else if mode=="recycle" {
                let count=std::thread::scope(|scope|->Result<usize,uls_parser::ParseError>{
                    let (sender,receiver)=sync_channel(2);
                    let (recycle,returned)=sync_channel::<Vec<uls_parser::Result<UlsRecord>>>(3);
                    let source=&mut zip;
                    let worker=scope.spawn(move ||{
                        let mut batch=Vec::with_capacity(256);
                        let result=source.process_dat_streaming(&file,|line|{
                            batch.push(line.to_record());
                            if batch.len()==256 {
                                sender.send(std::mem::take(&mut batch)).unwrap();
                                batch=returned.try_recv().unwrap_or_else(|_|Vec::with_capacity(256));
                                batch.clear();
                            }
                            true
                        });
                        if !batch.is_empty() {sender.send(batch).unwrap();}
                        result
                    });
                    let mut count=0;
                    for batch in receiver {
                        for record in &batch {
                            std::hint::black_box(record.as_ref().unwrap());count+=1;
                        }
                        let _=recycle.send(batch);
                    }
                    assert_eq!(worker.join().unwrap()?,count);
                    Ok(count)
                })?;
                records+=count;
            } else if mode=="records" {
                let count=std::thread::scope(|scope|->Result<usize,uls_parser::ParseError>{
                    let (sender,receiver)=sync_channel(2);
                    let source=&mut zip;
                    let worker=scope.spawn(move ||{
                        let mut batch=Vec::with_capacity(256);
                        let result=source.process_dat_streaming(&file,|line|{
                            batch.push(line.to_record());
                            if batch.len()==256 { sender.send(std::mem::replace(&mut batch,Vec::with_capacity(256))).unwrap(); }
                            true
                        });
                        if !batch.is_empty() {sender.send(batch).unwrap();}
                        result
                    });
                    let mut count=0;
                    for batch in receiver {for record in batch {consume(record).unwrap();count+=1;}}
                    assert_eq!(worker.join().unwrap()?,count);
                    Ok(count)
                })?;
                records+=count;
            } else {
                let count=std::thread::scope(|scope|->Result<usize,uls_parser::ParseError>{
                    let (sender,receiver)=sync_channel(2);
                    let source=&mut zip;
                    let worker=scope.spawn(move ||{
                        let mut batch=0;
                        let result=source.process_dat_streaming(&file,|line|{
                            consume(line.to_record()).unwrap();batch+=1;
                            if batch==256 {sender.send(batch).unwrap();batch=0;}
                            true
                        });
                        if batch!=0 {sender.send(batch).unwrap();}
                        result
                    });
                    let count:usize=receiver.into_iter().sum();
                    assert_eq!(worker.join().unwrap()?,count);
                    Ok(count)
                })?;
                records+=count;
            }
        }
    }
    assert_eq!(records,12_918_713);
    println!("mode={mode} records={records} seconds={}",start.elapsed().as_secs_f64());
    Ok(())
}
